41	+/**
42	+ * Shared `CorpusFS` contract suite (DD-009 sub-task S1).
43	+ *
44	+ * Any `CorpusFS` implementation must pass this. Run against the in-memory fake
45	+ * in CI (corpusFs.contract.test.ts) and against the real OPFS adapter via
46	+ * out-of-CI Playwright (jsdom has no OPFS). Keeping the cases in one place means
47	+ * the fake and the adapter are held to identical behavior (substitutability).
48	+ */
49	+
50	+import { describe, it, expect, beforeEach } from "vitest";
51	+import type { CorpusFS } from "../types";
52	+
53	+/** @param makeFs returns a fresh, empty CorpusFS for each test. */
54	+export function defineCorpusFsContract(label: string, makeFs: () => CorpusFS | Promise<CorpusFS>): void {
55	+  describe(`CorpusFS contract: ${label}`, () => {
56	+    let fs: CorpusFS;
57	+    beforeEach(async () => {
58	+      fs = await makeFs();
59	+    });
60	+
61	+    it("returns null for a missing file (readFile) and missing stat", async () => {
62	+      expect(await fs.readFile("absent.txt")).toBeNull();
63	+      expect(await fs.stat("absent.txt")).toBeNull();
64	+    });
65	+
66	+    it("returns [] for a missing/empty directory (readdir)", async () => {
67	+      expect(await fs.readdir("nope")).toEqual([]);
68	+    });
69	+
70	+    it("round-trips all 256 byte values exactly", async () => {
71	+      const bytes = new Uint8Array(256);
72	+      for (let i = 0; i < 256; i++) bytes[i] = i;
73	+      await fs.writeFile("bin/all-bytes.dat", bytes);
74	+      const out = await fs.readFile("bin/all-bytes.dat");
75	+      expect(out).not.toBeNull();
76	+      // Compare as arrays for a readable diff on failure.
77	+      expect(Array.from(out!)).toEqual(Array.from(bytes));
78	+      expect((await fs.stat("bin/all-bytes.dat"))?.size).toBe(256);
79	+    });
80	+
81	+    it("creates intermediate directories and lists children at each level", async () => {
82	+      await fs.writeFile("workspaces/s/artifacts/semiformal/v0001.md", new TextEncoder().encode("x"));
83	+      expect(await fs.readdir("workspaces")).toEqual(["s"]);
84	+      expect(await fs.readdir("workspaces/s")).toEqual(["artifacts"]);
85	+      expect(await fs.readdir("workspaces/s/artifacts")).toEqual(["semiformal"]);
86	+      expect(await fs.readdir("workspaces/s/artifacts/semiformal")).toEqual(["v0001.md"]);
87	+    });
88	+
89	+    it("rm removes a file and is idempotent on a missing path", async () => {
90	+      await fs.writeFile("a.txt", new TextEncoder().encode("hi"));
91	+      await fs.rm("a.txt");
92	+      expect(await fs.readFile("a.txt")).toBeNull();
93	+      // Second rm (and rm of never-existed) must not throw.
94	+      await expect(fs.rm("a.txt")).resolves.toBeUndefined();
95	+      await expect(fs.rm("never-existed.txt")).resolves.toBeUndefined();
96	+    });
97	+
98	+    it("handles the S4 access pattern: 30 small files in one artifact dir (arch-review finding 4)", async () => {
99	+      const dir = "workspaces/s/artifacts/semiformal";
100	+      for (let v = 1; v <= 30; v++) {
101	+        const name = `v${String(v).padStart(4, "0")}.md`;
102	+        await fs.writeFile(`${dir}/${name}`, new TextEncoder().encode(`version ${v}`));
103	+      }
104	+      const names = await fs.readdir(dir);
105	+      expect(names).toHaveLength(30);
106	+      expect(names).toContain("v0001.md");
107	+      expect(names).toContain("v0030.md");
108	+      // Read each back and confirm content integrity.
109	+      for (let v = 1; v <= 30; v++) {
110	+        const name = `v${String(v).padStart(4, "0")}.md`;
111	+        const bytes = await fs.readFile(`${dir}/${name}`);
112	+        expect(new TextDecoder().decode(bytes!)).toBe(`version ${v}`);
113	+      }
114	+    });
115	+
116	+    it("overwrites an existing file in place", async () => {
117	+      await fs.writeFile("a.txt", new TextEncoder().encode("first"));
118	+      await fs.writeFile("a.txt", new TextEncoder().encode("second"));
119	+      expect(new TextDecoder().decode((await fs.readFile("a.txt"))!)).toBe("second");
120	+    });
121	+  });
122	+}
