127	+++ b/app/lib/corpus/__tests__/inMemoryCorpusFs.ts
128	@@ -0,0 +1,53 @@
129	+/**
130	+ * Map-backed in-memory `CorpusFS` for tests (DD-009 sub-task S1).
131	+ *
132	+ * Lets corpus logic be verified in CI even though jsdom has no OPFS. The OPFS
133	+ * adapter and this fake are both asserted against the same shared contract suite
134	+ * (corpusFsContract.ts), so substitutability (LSP) is verified, not assumed.
135	+ *
136	+ * Directories are implicit: a file at "a/b/c.txt" makes "a" and "a/b" listable.
137	+ */
138	+
139	+import type { CorpusFS, CorpusStat } from "../types";
140	+
141	+function normalize(path: string): string {
142	+  return path.replace(/^\/+|\/+$/g, "");
143	+}
144	+
145	+export function createInMemoryCorpusFs(): CorpusFS {
146	+  const files = new Map<string, Uint8Array>();
147	+
148	+  return {
149	+    async readFile(path) {
150	+      return files.get(normalize(path)) ?? null;
151	+    },
152	+
153	+    async writeFile(path, bytes) {
154	+      // Copy so later mutation of the caller's array can't alter stored bytes.
155	+      files.set(normalize(path), bytes.slice());
156	+    },
157	+
158	+    async readdir(path) {
159	+      const dir = normalize(path);
160	+      const prefix = dir === "" ? "" : `${dir}/`;
161	+      const children = new Set<string>();
162	+      for (const key of files.keys()) {
163	+        if (prefix !== "" && !key.startsWith(prefix)) continue;
164	+        const rest = key.slice(prefix.length);
165	+        if (rest === "") continue;
166	+        const next = rest.split("/")[0];
167	+        if (next) children.add(next);
168	+      }
169	+      return [...children].sort();
170	+    },
171	+
172	+    async rm(path) {
173	+      files.delete(normalize(path)); // idempotent: Map.delete on a missing key is a no-op
174	+    },
175	+
176	+    async stat(path): Promise<CorpusStat | null> {
177	+      const bytes = files.get(normalize(path));
178	+      return bytes ? { size: bytes.byteLength } : null;
179	+    },
180	+  };
181	+}
