246	+/**
247	+ * OPFS adapter error-mapping tests (DD-009 S1, test-strategy G7/G8).
248	+ *
249	+ * jsdom has no real OPFS, so these stub `navigator.storage` to drive the
250	+ * adapter's error-reification logic. The adapter's *success* path is covered by
251	+ * the shared CorpusFS contract suite run against real OPFS out-of-CI (Playwright,
252	+ * step 9) — here we only assert that failures become typed CorpusErrors.
253	+ */
254	+
255	+import { describe, it, expect, afterEach } from "vitest";
256	+import { createOpfsCorpusFs } from "../opfsAdapter";
257	+import { CorpusError } from "../types";
258	+
259	+const original = Object.getOwnPropertyDescriptor(navigator, "storage");
260	+
261	+function setStorage(value: unknown): void {
262	+  Object.defineProperty(navigator, "storage", { configurable: true, value });
263	+}
264	+
265	+afterEach(() => {
266	+  if (original) Object.defineProperty(navigator, "storage", original);
267	+  else setStorage(undefined);
268	+});
