288	+    await expect(fs.writeFile("x", new Uint8Array())).rejects.toBeInstanceOf(CorpusError);
289	+    await expect(fs.readdir("x")).rejects.toBeInstanceOf(CorpusError);
290	+    await expect(fs.stat("x")).rejects.toBeInstanceOf(CorpusError);
291	+    await expect(fs.rm("x")).rejects.toBeInstanceOf(CorpusError);
