408	+/**
409	+ * Corpus feature flag (DD-009 sub-task S1).
410	+ *
411	+ * DEFAULT OFF and DEV-ONLY. In S1 there is no localStorage->corpus migration
412	+ * (that is S4), so enabling this starts from an EMPTY corpus and does not carry
413	+ * existing localStorage work over. It exists only to let developers exercise the
414	+ * OPFS path; it must not be turned on for end users until S4 ships migration.
415	+ *
416	+ * Enable via either the build-time env `NEXT_PUBLIC_CORPUS_FS=1` or, at runtime
417	+ * in a dev browser, `localStorage.setItem("corpus-fs-enabled", "1")`.
418	+ */
419	+
420	+export const CORPUS_FLAG_KEY = "corpus-fs-enabled";
421	+
422	+export function isCorpusEnabled(): boolean {
423	+  if (typeof process !== "undefined" && process.env?.NEXT_PUBLIC_CORPUS_FS === "1") return true;
424	+  if (typeof window !== "undefined") {
425	+    try {
426	+      return window.localStorage.getItem(CORPUS_FLAG_KEY) === "1";
427	+    } catch {
428	+      return false;
429	+    }
430	+  }
431	+  return false;
432	+}
