438	@@ -0,0 +1,115 @@
439	+/**
440	+ * `workspace.json` manifest schema + codec (DD-009 sub-task S0).
441	+ *
442	+ * The manifest is the index for one workspace folder: it lists the sources, the
443	+ * current-version pointer per artifact type, and the custom-type ids present.
444	+ * The per-version artifact bytes live in files (artifacts/<type>/v####.md), not
445	+ * here — the manifest only points at the current version so a consumer can open
446	+ * a workspace without scanning every file.
447	+ *
448	+ * Codec contract (arch-review / test-strategy G11): parsing is FAIL-LOUD. A
449	+ * malformed or absent manifest must surface as a typed `CorpusError` of kind
450	+ * "io" or "browser-storage-cleared", never a silent default-empty manifest that
451	+ * would masquerade as "this workspace has no work in it" and mask data loss.
452	+ */
453	+
454	+import { CorpusError } from "./types";
455	+
456	+export const MANIFEST_VERSION = 1;
457	+
458	+/** Pointer to the current version of one artifact type. `currentVersion` is the
459	+ *  1-based version number whose file is artifacts/<type>/v####.md. */
460	+export interface ArtifactPointer {
461	+  type: string;
462	+  currentVersion: number;
463	+}
464	+
465	+export interface SourceRef {
466	+  id: string;
467	+  label: string;
468	+  /** File extension (no dot) of the stored source bytes under sources/. */
469	+  ext: string;
470	+}
471	+
472	+export interface WorkspaceManifest {
473	+  manifestVersion: number;
474	+  title: string;
475	+  createdAt: string;
476	+  updatedAt: string;
477	+  sources: SourceRef[];
478	+  artifacts: ArtifactPointer[];
479	+  customTypeIds: string[];
480	+}
481	+
482	+export function createManifest(title: string, now = new Date().toISOString()): WorkspaceManifest {
483	+  return {
484	+    manifestVersion: MANIFEST_VERSION,
485	+    title,
486	+    createdAt: now,
487	+    updatedAt: now,
488	+    sources: [],
489	+    artifacts: [],
490	+    customTypeIds: [],
491	+  };
492	+}
493	+
494	+export function serializeManifest(m: WorkspaceManifest): Uint8Array {
495	+  return new TextEncoder().encode(JSON.stringify(m, null, 2));
496	+}
497	+
498	+function isObject(v: unknown): v is Record<string, unknown> {
499	+  return typeof v === "object" && v !== null && !Array.isArray(v);
500	+}
501	+
502	+function fail(reason: string): never {
503	+  // Manifest parse failure is an i/o-class corruption of the workspace index.
504	+  throw new CorpusError({ kind: "io", path: "workspace.json", reason }, `invalid workspace.json: ${reason}`);
505	+}
506	+
507	+/**
508	+ * Parse + validate manifest bytes. Throws a `CorpusError` on any malformation —
509	+ * a `null` input (file absent) is the caller's responsibility to detect via
510	+ * `CorpusFS.readFile` returning `null`; passing `null` here is itself an error.
511	+ */
512	+export function parseManifest(bytes: Uint8Array | null): WorkspaceManifest {
513	+  if (bytes === null) fail("manifest file is absent");
514	+  let raw: unknown;
515	+  try {
516	+    raw = JSON.parse(new TextDecoder().decode(bytes));
517	+  } catch (e) {
518	+    fail(`not valid JSON (${(e as Error).message})`);
519	+  }
520	+  if (!isObject(raw)) fail("top-level value is not an object");
521	+  if (typeof raw.title !== "string") fail("missing required field: title");
522	+  if (typeof raw.manifestVersion !== "number") fail("missing required field: manifestVersion");
523	+
524	+  const sources: SourceRef[] = Array.isArray(raw.sources)
525	+    ? raw.sources.filter(isObject).map((s) => {
526	+        if (typeof s.id !== "string" || typeof s.ext !== "string") fail("source entry missing id/ext");
527	+        return { id: s.id, label: typeof s.label === "string" ? s.label : s.id, ext: s.ext };
528	+      })
529	+    : fail("missing or invalid field: sources");
530	+
531	+  const artifacts: ArtifactPointer[] = Array.isArray(raw.artifacts)
532	+    ? raw.artifacts.filter(isObject).map((a) => {
533	+        if (typeof a.type !== "string" || typeof a.currentVersion !== "number") {
534	+          fail("artifact pointer missing type/currentVersion");
535	+        }
536	+        return { type: a.type as string, currentVersion: a.currentVersion as number };
537	+      })
538	+    : fail("missing or invalid field: artifacts");
539	+
540	+  const customTypeIds: string[] = Array.isArray(raw.customTypeIds)
541	+    ? raw.customTypeIds.filter((x): x is string => typeof x === "string")
542	+    : fail("missing or invalid field: customTypeIds");
543	+
544	+  return {
545	+    manifestVersion: raw.manifestVersion,
546	+    title: raw.title,
547	+    createdAt: typeof raw.createdAt === "string" ? raw.createdAt : new Date().toISOString(),
548	+    updatedAt: typeof raw.updatedAt === "string" ? raw.updatedAt : new Date().toISOString(),
549	+    sources,
550	+    artifacts,
551	+    customTypeIds,
552	+  };
553	+}
