559	@@ -0,0 +1,176 @@
560	+/**
561	+ * OPFS-backed `CorpusFS` adapter (DD-009 sub-task S1).
562	+ *
563	+ * Implements the corpus filesystem over the Origin Private File System
564	+ * (`navigator.storage.getDirectory()`). This is the always-on local working
565	+ * copy; FSA mirror (S2) and git (S3) layer on top.
566	+ *
567	+ * Two contracts this file is responsible for (test-strategy G7/G8, arch-review):
568	+ *  - SSR / unavailable guard: any call in an environment without
569	+ *    `navigator.storage.getDirectory` rejects with a typed `CorpusError`
570	+ *    ({kind:"unavailable"}), never a raw `TypeError`.
571	+ *  - Failure reification: a quota failure rejects with {kind:"quota-exceeded",
572	+ *    substrate:"opfs"} — it is NOT swallowed with console.warn the way the
573	+ *    legacy localStorage adapter does (workspaceStore.ts:44-46).
574	+ *
575	+ * OPFS handle types are declared locally rather than relying on lib.dom, whose
576	+ * OPFS surface (notably async `keys()`) varies by TypeScript version — keeping
577	+ * our own minimal shapes makes the build stable across upgrades.
578	+ */
579	+
580	+import type { CorpusFS, CorpusStat } from "./types";
581	+import { CorpusError } from "./types";
582	+
583	+// --- Minimal local OPFS typings ---
584	+interface OpfsWritable {
585	+  // We only ever write Uint8Array; typing it narrowly avoids the lib.dom
586	+  // BufferSource/ArrayBufferLike strictness mismatch across TS versions.
587	+  write(data: Uint8Array): Promise<void>;
588	+  close(): Promise<void>;
589	+}
590	+interface OpfsFileHandle {
591	+  getFile(): Promise<{ size: number; arrayBuffer(): Promise<ArrayBuffer> }>;
592	+  createWritable(): Promise<OpfsWritable>;
593	+}
594	+interface OpfsDirHandle {
595	+  getFileHandle(name: string, opts?: { create?: boolean }): Promise<OpfsFileHandle>;
596	+  getDirectoryHandle(name: string, opts?: { create?: boolean }): Promise<OpfsDirHandle>;
597	+  removeEntry(name: string, opts?: { recursive?: boolean }): Promise<void>;
598	+  keys(): AsyncIterableIterator<string>;
599	+}
600	+
601	+function isNotFound(e: unknown): boolean {
602	+  return e instanceof DOMException && (e.name === "NotFoundError" || e.name === "TypeMismatchError");
603	+}
604	+function isQuota(e: unknown): boolean {
605	+  return e instanceof DOMException && (e.name === "QuotaExceededError" || e.name === "QUOTA_EXCEEDED_ERR");
606	+}
607	+
608	+async function getRoot(): Promise<OpfsDirHandle> {
609	+  const storage = typeof navigator !== "undefined" ? navigator.storage : undefined;
610	+  if (!storage || typeof storage.getDirectory !== "function") {
611	+    throw new CorpusError({ kind: "unavailable", reason: "navigator.storage.getDirectory is not available (SSR or unsupported browser)" });
612	+  }
613	+  return (await storage.getDirectory()) as unknown as OpfsDirHandle;
614	+}
615	+
616	+function splitPath(path: string): { dirs: string[]; name: string } {
617	+  const parts = path.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
618	+  const name = parts.pop();
619	+  if (!name) throw new CorpusError({ kind: "io", path, reason: "path has no file component" });
620	+  return { dirs: parts, name };
621	+}
622	+
623	+/** Walk (optionally creating) directory handles for the given segments. Returns
624	+ *  null when `create` is false and a segment is missing. */
625	+async function walkDir(root: OpfsDirHandle, dirs: string[], create: boolean): Promise<OpfsDirHandle | null> {
626	+  let cur = root;
627	+  for (const d of dirs) {
628	+    try {
629	+      cur = await cur.getDirectoryHandle(d, { create });
630	+    } catch (e) {
631	+      if (!create && isNotFound(e)) return null;
632	+      throw e;
633	+    }
634	+  }
635	+  return cur;
636	+}
637	+
638	+function wrap(path: string, e: unknown): never {
639	+  if (e instanceof CorpusError) throw e;
640	+  if (isQuota(e)) throw new CorpusError({ kind: "quota-exceeded", substrate: "opfs" });
641	+  throw new CorpusError({ kind: "io", path, reason: (e as Error)?.message ?? String(e) });
642	+}
643	+
644	+export function createOpfsCorpusFs(): CorpusFS {
645	+  return {
646	+    async readFile(path) {
647	+      try {
648	+        const root = await getRoot();
649	+        const { dirs, name } = splitPath(path);
650	+        const dir = await walkDir(root, dirs, false);
651	+        if (!dir) return null;
652	+        let fh: OpfsFileHandle;
653	+        try {
654	+          fh = await dir.getFileHandle(name, { create: false });
655	+        } catch (e) {
656	+          if (isNotFound(e)) return null;
657	+          throw e;
658	+        }
659	+        const file = await fh.getFile();
660	+        return new Uint8Array(await file.arrayBuffer());
661	+      } catch (e) {
662	+        wrap(path, e);
663	+      }
664	+    },
665	+
666	+    async writeFile(path, bytes) {
667	+      try {
668	+        const root = await getRoot();
669	+        const { dirs, name } = splitPath(path);
670	+        const dir = await walkDir(root, dirs, true);
671	+        const fh = await dir!.getFileHandle(name, { create: true });
672	+        const w = await fh.createWritable();
673	+        try {
674	+          // Pass a fresh ArrayBuffer view; some implementations dislike shared buffers.
675	+          await w.write(bytes);
676	+        } finally {
677	+          await w.close();
678	+        }
679	+      } catch (e) {
680	+        wrap(path, e);
681	+      }
682	+    },
683	+
684	+    async readdir(path) {
685	+      try {
686	+        const root = await getRoot();
687	+        const dirs = path.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
688	+        const dir = await walkDir(root, dirs, false);
689	+        if (!dir) return [];
690	+        const names: string[] = [];
691	+        for await (const key of dir.keys()) names.push(key);
692	+        return names.sort();
693	+      } catch (e) {
694	+        wrap(path, e);
695	+      }
696	+    },
697	+
698	+    async rm(path) {
699	+      try {
700	+        const root = await getRoot();
701	+        const { dirs, name } = splitPath(path);
702	+        const dir = await walkDir(root, dirs, false);
703	+        if (!dir) return; // idempotent: parent dir missing -> nothing to remove
704	+        try {
705	+          await dir.removeEntry(name);
706	+        } catch (e) {
707	+          if (isNotFound(e)) return; // idempotent: file already gone
708	+          throw e;
709	+        }
710	+      } catch (e) {
711	+        wrap(path, e);
712	+      }
713	+    },
714	+
715	+    async stat(path): Promise<CorpusStat | null> {
716	+      try {
717	+        const root = await getRoot();
718	+        const { dirs, name } = splitPath(path);
719	+        const dir = await walkDir(root, dirs, false);
720	+        if (!dir) return null;
721	+        let fh: OpfsFileHandle;
722	+        try {
723	+          fh = await dir.getFileHandle(name, { create: false });
724	+        } catch (e) {
725	+          if (isNotFound(e)) return null;
726	+          throw e;
727	+        }
728	+        const file = await fh.getFile();
729	+        return { size: file.size };
730	+      } catch (e) {
731	+        wrap(path, e);
732	+      }
733	+    },
734	+  };
735	+}
