742	+/**
743	+ * Corpus folder-layout path builders (DD-009 sub-task S0).
744	+ *
745	+ * The on-disk shape (DD-009 §Folder layout):
746	+ *
747	+ *   <corpus-root>/
748	+ *   ├── settings.json
749	+ *   └── workspaces/<slug>/
750	+ *       ├── workspace.json
751	+ *       ├── sources/<source-id>.<ext>
752	+ *       ├── artifacts/<type>/v####.md   (+ meta.json per type)
753	+ *       ├── custom-types/<custom-type-id>.json
754	+ *       └── decomposition/...
755	+ *
756	+ * All builders return POSIX-style paths relative to the corpus root (no leading
757	+ * slash), suitable for passing straight to a `CorpusFS`. The only source of
758	+ * corpus paths is this module — callers must never hand-concatenate, so the
759	+ * traversal guard in `workspaceSlug` is the single choke point that keeps
760	+ * untrusted workspace titles inside `workspaces/`.
761	+ */
762	+
763	+/** Width of the zero-padded version number in artifact filenames (v0001.md). */
764	+const VERSION_PAD = 4;
765	+
766	+/** Characters allowed in a sanitized slug or id segment. Everything else is
767	+ *  collapsed to a hyphen so a value can never contain "/", "\\", "." runs, or
768	+ *  control characters that would let it escape its directory. */
769	+const SAFE_SEGMENT = /[^a-zA-Z0-9_-]+/g;
770	+
771	+/**
772	+ * Sanitize a workspace title into a filesystem-safe slug that cannot escape
773	+ * `workspaces/`. Strips path separators, dot-segments, and unicode; collapses
774	+ * runs of unsafe characters to a single hyphen; trims leading/trailing hyphens.
775	+ * Throws if nothing safe remains (an all-unsafe title must not silently become "").
776	+ */
777	+export function workspaceSlug(title: string): string {
778	+  const slug = title
779	+    .normalize("NFKD")
780	+    .replace(SAFE_SEGMENT, "-")
781	+    .replace(/-{2,}/g, "-")
782	+    .replace(/^-+|-+$/g, "")
783	+    .toLowerCase();
784	+  if (!slug) {
785	+    throw new Error(`workspace title produced an empty slug: ${JSON.stringify(title)}`);
786	+  }
787	+  return slug;
788	+}
789	+
790	+/** Sanitize an arbitrary id (source id, custom-type id, artifact type) for use
791	+ *  as a single path segment. Same guarantees as `workspaceSlug` but preserves
792	+ *  case (ids are typically already safe, e.g. "custom-abc123"). */
793	+export function safeSegment(id: string): string {
794	+  const seg = id.normalize("NFKD").replace(SAFE_SEGMENT, "-").replace(/-{2,}/g, "-").replace(/^-+|-+$/g, "");
795	+  if (!seg) {
796	+    throw new Error(`id produced an empty path segment: ${JSON.stringify(id)}`);
797	+  }
798	+  return seg;
799	+}
800	+
801	+/** Sanitize a file extension to alphanumerics; defaults to "bin" if empty. */
802	+function safeExt(ext: string): string {
803	+  const e = ext.replace(/^\.+/, "").replace(/[^a-zA-Z0-9]+/g, "").toLowerCase();
804	+  return e || "bin";
805	+}
806	+
807	+// --- Path builders (all relative to corpus root) ---------------------------
808	+
809	+export const SETTINGS_PATH = "settings.json";
810	+
811	+export function workspaceDir(slug: string): string {
812	+  return `workspaces/${workspaceSlug(slug)}`;
813	+}
814	+
815	+export function workspaceManifestPath(slug: string): string {
816	+  return `${workspaceDir(slug)}/workspace.json`;
817	+}
818	+
819	+export function sourcePath(slug: string, sourceId: string, ext: string): string {
820	+  return `${workspaceDir(slug)}/sources/${safeSegment(sourceId)}.${safeExt(ext)}`;
821	+}
822	+
823	+export function artifactDir(slug: string, artifactType: string): string {
824	+  return `${workspaceDir(slug)}/artifacts/${safeSegment(artifactType)}`;
825	+}
826	+
827	+/** Zero-padded version file, e.g. artifactVersionPath(s,"semiformal",1) ->
828	+ *  "workspaces/<s>/artifacts/semiformal/v0001.md". `version` is 1-based. */
829	+export function artifactVersionPath(slug: string, artifactType: string, version: number): string {
830	+  if (!Number.isInteger(version) || version < 1) {
831	+    throw new Error(`artifact version must be a positive integer, got ${version}`);
832	+  }
833	+  const v = String(version).padStart(VERSION_PAD, "0");
834	+  return `${artifactDir(slug, artifactType)}/v${v}.md`;
835	+}
836	+
837	+export function artifactMetaPath(slug: string, artifactType: string): string {
838	+  return `${artifactDir(slug, artifactType)}/meta.json`;
839	+}
840	+
841	+export function customTypePath(slug: string, customTypeId: string): string {
842	+  return `${workspaceDir(slug)}/custom-types/${safeSegment(customTypeId)}.json`;
843	+}
844	+
845	+export function decompositionDir(slug: string): string {
846	+  return `${workspaceDir(slug)}/decomposition`;
847	+}
848	+
849	+export function decompositionGraphLayoutPath(slug: string): string {
850	+  return `${decompositionDir(slug)}/graph-layout.json`;
851	+}
