858	+/**
859	+ * Storage-seam selection for the Zustand workspace store (DD-009 sub-task S1).
860	+ *
861	+ * `resolveWorkspaceStorage()` returns the zustand persist storage: the existing
862	+ * debounced localStorage adapter by default, or a CorpusFS-backed storage when
863	+ * the dev flag is on. The injection seam is typed as `CorpusFS` (arch-review
864	+ * finding 3) so the S3 worker-proxy implementation drops in here without the
865	+ * store ever knowing which adapter it talks to.
866	+ *
867	+ * In S1 the persist blob is stored as a SINGLE file via CorpusFS (blob mode) —
868	+ * the files-per-artifact folder layout (layout.ts/manifest.ts) is built but not
869	+ * used by the store until S4. This keeps S1 a pure substrate swap.
870	+ */
871	+
872	+import type { StateStorage } from "zustand/middleware";
873	+import type { CorpusFS } from "./types";
874	+import { createOpfsCorpusFs } from "./opfsAdapter";
875	+import { isCorpusEnabled } from "./flag";
876	+
877	+// ---------------------------------------------------------------------------
878	+// Default: debounced localStorage (moved verbatim from workspaceStore.ts so the
879	+// OFF path is byte-for-byte the prior behavior — see the characterization test).
880	+// Reads are synchronous (instant); writes are debounced by 300ms.
881	+// ---------------------------------------------------------------------------
882	+export function createDebouncedLocalStorage(): StateStorage {
883	+  let pending: ReturnType<typeof setTimeout> | null = null;
884	+  return {
885	+    getItem: (name) => localStorage.getItem(name),
886	+    setItem: (name, value) => {
887	+      if (pending) clearTimeout(pending);
888	+      pending = setTimeout(() => {
889	+        try {
890	+          localStorage.setItem(name, value);
891	+        } catch (e) {
892	+          console.warn("Failed to persist workspace (localStorage quota exceeded):", e);
893	+        }
894	+        pending = null;
895	+      }, 300);
896	+    },
897	+    removeItem: (name) => {
898	+      if (pending) clearTimeout(pending);
899	+      pending = null;
900	+      localStorage.removeItem(name);
901	+    },
902	+  };
903	+}
904	+
905	+// ---------------------------------------------------------------------------
906	+// Corpus-backed storage: stores the persist blob as one file under `state/`.
907	+// The seam type is CorpusFS, not a concrete adapter (arch-review finding 3).
908	+// ---------------------------------------------------------------------------
909	+export function createCorpusBackedStorage(fs: CorpusFS): StateStorage {
910	+  const enc = new TextEncoder();
911	+  const dec = new TextDecoder();
912	+  const pathFor = (name: string) => `state/${name}.json`;
913	+  return {
914	+    getItem: async (name) => {
915	+      const bytes = await fs.readFile(pathFor(name));
916	+      return bytes ? dec.decode(bytes) : null;
917	+    },
918	+    setItem: async (name, value) => {
919	+      await fs.writeFile(pathFor(name), enc.encode(value));
920	+    },
921	+    removeItem: async (name) => {
922	+      await fs.rm(pathFor(name));
923	+    },
924	+  };
925	+}
926	+
927	+/** Selected once when the store's persist middleware initializes. */
928	+export function resolveWorkspaceStorage(): StateStorage {
929	+  if (isCorpusEnabled()) {
930	+    return createCorpusBackedStorage(createOpfsCorpusFs());
931	+  }
932	+  return createDebouncedLocalStorage();
933	+}
