937	--- /dev/null
938	+++ b/app/lib/corpus/types.ts
939	@@ -0,0 +1,125 @@
940	+/**
941	+ * Corpus filesystem abstraction (DD-009 sub-task S0+S1).
942	+ *
943	+ * `CorpusFS` is the single FS seam every later sub-task binds to:
944	+ *   - S1 OPFS adapter implements it (always-on local cache)
945	+ *   - S2 FSA folder mirror writes through it
946	+ *   - S4 migration + session model reads/writes the folder layout through it
947	+ *
948	+ * Design notes (see docs/decisions/009-artifact-corpus-architecture.md and
949	+ * docs/reviews/architecture-review.md):
950	+ *  - Bytes + paths, not strings + keys. Sources are binary (PDFs), so the
951	+ *    interface is `Uint8Array`-oriented; do not narrow it to strings.
952	+ *  - Async everywhere. OPFS and FSA are both async, and DD-009 mandates the
953	+ *    writer eventually run in a worker (S3). An async interface makes that a
954	+ *    transport swap, not an interface change — so consumers MUST bind to this
955	+ *    interface, never to a concrete adapter (arch-review finding 3).
956	+ *  - "Not found" is `null` from `readFile`/`stat` and `[]` from `readdir`;
957	+ *    everything else rejects with a `CorpusError`. Callers never see `undefined`.
958	+ *  - GIT IS NOT PART OF THIS INTERFACE. S3's commit/log/push/pull belong on a
959	+ *    separate `CorpusGit` interface that operates *over* a `CorpusFS`. Do not add
960	+ *    git methods here — that would force the in-memory fake and every non-git
961	+ *    consumer to stub operations they don't use (arch-review finding 2, ISP).
962	+ */
963	+
964	+// ---------------------------------------------------------------------------
965	+// Error model — one source of truth for the kind set (arch-review finding 1).
966	+// `CorpusError` is the thrown form; `CorpusWorkerError` is its postMessage-
967	+// serializable twin. They differ only in transport, never in the kind set.
968	+// ---------------------------------------------------------------------------
969	+
970	+/** Which substrate raised a space/quota failure. Substrate-neutral so S2 (FSA)
971	+ *  and future caches reuse the same `quota-exceeded` kind rather than minting
972	+ *  adapter-specific kinds the exhaustive switches would all have to learn. */
973	+export type CorpusSubstrate = "opfs" | "fsa" | "remote";
974	+
975	+/**
976	+ * The complete set of corpus failure kinds. Every exhaustive `switch` over a
977	+ * corpus error binds to this union; adding a kind here forces every consumer to
978	+ * handle it at compile time (the failure-driven-UI mandate, DD-009 §Failure-driven).
979	+ */
980	+export type CorpusErrorKind =
981	+  | { kind: "not-found"; path: string }
982	+  | { kind: "quota-exceeded"; substrate: CorpusSubstrate; needed?: number; available?: number }
983	+  | { kind: "unavailable"; reason: string } // e.g. SSR / no navigator.storage
984	+  | { kind: "io"; path: string; reason: string }
985	+  | { kind: "fsa-permission-revoked" }
986	+  | { kind: "remote-auth-expired" }
987	+  | { kind: "browser-storage-cleared" }
988	+  | { kind: "git-conflict"; path: string };
989	+
990	+/** Thrown form of a corpus failure. `detail` carries the discriminated kind. */
991	+export class CorpusError extends Error {
992	+  readonly detail: CorpusErrorKind;
993	+  constructor(detail: CorpusErrorKind, message?: string) {
994	+    super(message ?? describeCorpusError(detail));
995	+    this.name = "CorpusError";
996	+    this.detail = detail;
997	+  }
998	+}
999	+
