 * existing localStorage work over. It exists only to let developers exercise the
 * OPFS path; it must not be turned on for end users until S4 ships migration.
 *
 * Enable via either the build-time env `NEXT_PUBLIC_CORPUS_FS=1` or, at runtime
 * in a dev browser, `localStorage.setItem("corpus-fs-enabled", "1")`.
 */

export const CORPUS_FLAG_KEY = "corpus-fs-enabled";

export function isCorpusEnabled(): boolean {
  if (typeof process !== "undefined" && process.env?.NEXT_PUBLIC_CORPUS_FS === "1") return true;
  if (typeof window !== "undefined") {
    try {
      return window.localStorage.getItem(CORPUS_FLAG_KEY) === "1";
    } catch {
      return false;
    }
  }
  return false;
}
/**
 * Corpus folder-layout path builders (DD-009 sub-task S0).
 *
 * The on-disk shape (DD-009 §Folder layout):
 *
 *   <corpus-root>/
 *   ├── settings.json
 *   └── workspaces/<slug>/
 *       ├── workspace.json
 *       ├── sources/<source-id>.<ext>
 *       ├── artifacts/<type>/v####.md   (+ meta.json per type)
 *       ├── custom-types/<custom-type-id>.json
 *       └── decomposition/...
 *
 * All builders return POSIX-style paths relative to the corpus root (no leading
 * slash), suitable for passing straight to a `CorpusFS`. The only source of
 * corpus paths is this module — callers must never hand-concatenate, so the
 * traversal guard in `workspaceSlug` is the single choke point that keeps
 * untrusted workspace titles inside `workspaces/`.
 */

/** Width of the zero-padded version number in artifact filenames (v0001.md). */
const VERSION_PAD = 4;

/** Characters allowed in a sanitized slug or id segment. Everything else is
 *  collapsed to a hyphen so a value can never contain "/", "\\", "." runs, or
 *  control characters that would let it escape its directory. */
const SAFE_SEGMENT = /[^a-zA-Z0-9_-]+/g;

/**
 * Sanitize a workspace title into a filesystem-safe slug that cannot escape
 * `workspaces/`. Strips path separators, dot-segments, and unicode; collapses
 * runs of unsafe characters to a single hyphen; trims leading/trailing hyphens.
 * Throws if nothing safe remains (an all-unsafe title must not silently become "").
 */
export function workspaceSlug(title: string): string {
  const slug = title
    .normalize("NFKD")
    .replace(SAFE_SEGMENT, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^-+|-+$/g, "")
    .toLowerCase();
  if (!slug) {
    throw new Error(`workspace title produced an empty slug: ${JSON.stringify(title)}`);
  }
  return slug;
}

/** Sanitize an arbitrary id (source id, custom-type id, artifact type) for use
 *  as a single path segment. Same guarantees as `workspaceSlug` but preserves
 *  case (ids are typically already safe, e.g. "custom-abc123"). */
export function safeSegment(id: string): string {
  const seg = id.normalize("NFKD").replace(SAFE_SEGMENT, "-").replace(/-{2,}/g, "-").replace(/^-+|-+$/g, "");
  if (!seg) {
    throw new Error(`id produced an empty path segment: ${JSON.stringify(id)}`);
  }
  return seg;
}

/** Sanitize a file extension to alphanumerics; defaults to "bin" if empty. */
function safeExt(ext: string): string {
  const e = ext.replace(/^\.+/, "").replace(/[^a-zA-Z0-9]+/g, "").toLowerCase();
  return e || "bin";
}

// --- Path builders (all relative to corpus root) ---------------------------

export const SETTINGS_PATH = "settings.json";

export function workspaceDir(slug: string): string {
  return `workspaces/${workspaceSlug(slug)}`;
}

export function workspaceManifestPath(slug: string): string {
  return `${workspaceDir(slug)}/workspace.json`;
}

export function sourcePath(slug: string, sourceId: string, ext: string): string {
  return `${workspaceDir(slug)}/sources/${safeSegment(sourceId)}.${safeExt(ext)}`;
}

export function artifactDir(slug: string, artifactType: string): string {
  return `${workspaceDir(slug)}/artifacts/${safeSegment(artifactType)}`;
}

/** Zero-padded version file, e.g. artifactVersionPath(s,"semiformal",1) ->
 *  "workspaces/<s>/artifacts/semiformal/v0001.md". `version` is 1-based. */
export function artifactVersionPath(slug: string, artifactType: string, version: number): string {
  if (!Number.isInteger(version) || version < 1) {
    throw new Error(`artifact version must be a positive integer, got ${version}`);
  }
  const v = String(version).padStart(VERSION_PAD, "0");
  return `${artifactDir(slug, artifactType)}/v${v}.md`;
}

export function artifactMetaPath(slug: string, artifactType: string): string {
  return `${artifactDir(slug, artifactType)}/meta.json`;
}

export function customTypePath(slug: string, customTypeId: string): string {
  return `${workspaceDir(slug)}/custom-types/${safeSegment(customTypeId)}.json`;
}

export function decompositionDir(slug: string): string {
  return `${workspaceDir(slug)}/decomposition`;
}

export function decompositionGraphLayoutPath(slug: string): string {
  return `${decompositionDir(slug)}/graph-layout.json`;
}
/**
 * Storage-seam selection for the Zustand workspace store (DD-009 sub-task S1).
 *
 * `resolveWorkspaceStorage()` returns the zustand persist storage: the existing
 * debounced localStorage adapter by default, or a CorpusFS-backed storage when
 * the dev flag is on. The injection seam is typed as `CorpusFS` (arch-review
 * finding 3) so the S3 worker-proxy implementation drops in here without the
 * store ever knowing which adapter it talks to.
 *
 * In S1 the persist blob is stored as a SINGLE file via CorpusFS (blob mode) —
 * the files-per-artifact folder layout (layout.ts/manifest.ts) is built but not
 * used by the store until S4. This keeps S1 a pure substrate swap.
 */

import type { StateStorage } from "zustand/middleware";
import type { CorpusFS } from "./types";
import { createOpfsCorpusFs } from "./opfsAdapter";
import { isCorpusEnabled } from "./flag";

// ---------------------------------------------------------------------------
// Default: debounced localStorage (moved verbatim from workspaceStore.ts so the
// OFF path is byte-for-byte the prior behavior — see the characterization test).
// Reads are synchronous (instant); writes are debounced by 300ms.
// ---------------------------------------------------------------------------
export function createDebouncedLocalStorage(): StateStorage {
  let pending: ReturnType<typeof setTimeout> | null = null;
  return {
    getItem: (name) => localStorage.getItem(name),
    setItem: (name, value) => {
      if (pending) clearTimeout(pending);
      pending = setTimeout(() => {
        try {
          localStorage.setItem(name, value);
        } catch (e) {
          console.warn("Failed to persist workspace (localStorage quota exceeded):", e);
        }
        pending = null;
      }, 300);
    },
    removeItem: (name) => {
      if (pending) clearTimeout(pending);
      pending = null;
      localStorage.removeItem(name);
    },
  };
}

// ---------------------------------------------------------------------------
// Corpus-backed storage: stores the persist blob as one file under `state/`.
// The seam type is CorpusFS, not a concrete adapter (arch-review finding 3).
// ---------------------------------------------------------------------------
export function createCorpusBackedStorage(fs: CorpusFS): StateStorage {
  const enc = new TextEncoder();
  const dec = new TextDecoder();
  const pathFor = (name: string) => `state/${name}.json`;
  return {
    getItem: async (name) => {
      const bytes = await fs.readFile(pathFor(name));
      return bytes ? dec.decode(bytes) : null;
    },
    setItem: async (name, value) => {
      await fs.writeFile(pathFor(name), enc.encode(value));
    },
    removeItem: async (name) => {
      await fs.rm(pathFor(name));
    },
  };
}

/** Selected once when the store's persist middleware initializes. */
export function resolveWorkspaceStorage(): StateStorage {
  if (isCorpusEnabled()) {
    return createCorpusBackedStorage(createOpfsCorpusFs());
  }
  return createDebouncedLocalStorage();
}
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

import type { PropositionNode, NodeVerificationStatus } from "@/app/lib/types/decomposition";
import type { VerificationStatus } from "@/app/lib/types/session";
import type { PersistedWorkspace, PersistedDecomposition } from "@/app/lib/types/persistence";
import { WORKSPACE_VERSION, WORKSPACE_KEY } from "@/app/lib/types/persistence";
import type { CustomArtifactTypeDefinition } from "@/app/lib/types/customArtifact";

const LEGACY_WORKSPACE_KEY = "workspace-v1";

/** Migrate legacy workspace-v1 data to workspace-v2 key, then remove the old key. */
export function migrateV1Workspace(): void {
  try {
    const raw = localStorage.getItem(LEGACY_WORKSPACE_KEY);
    if (!raw) return;

    // Only migrate if there's no v2 data yet
    if (localStorage.getItem(WORKSPACE_KEY)) {
      localStorage.removeItem(LEGACY_WORKSPACE_KEY);
      return;
    }

    const parsed: unknown = JSON.parse(raw);
    if (isObject(parsed)) {
      // Stamp with current version so loadWorkspace accepts it
      (parsed as Record<string, unknown>).version = WORKSPACE_VERSION;
      localStorage.setItem(WORKSPACE_KEY, JSON.stringify(parsed));
    }
    localStorage.removeItem(LEGACY_WORKSPACE_KEY);
  } catch {
    // Best-effort; don't block app startup
    try { localStorage.removeItem(LEGACY_WORKSPACE_KEY); } catch { /* ignore */ }
  }
}

/** Strip transient "verifying" status back to "none" */
export function sanitizeVerificationStatus(status: string): "none" | "valid" | "invalid" {
  if (status === "valid" || status === "invalid") return status;
  return "none";
}

/** Strip transient "in-progress" node status back to "unverified" */
export function sanitizeNodeStatus(status: string): NodeVerificationStatus {
  if (status === "verified" || status === "failed" || status === "unverified") {
    return status;
  }
  return "unverified";
}

function sanitizeNode(node: PropositionNode): PropositionNode {
  return {
    ...node,
    verificationStatus: sanitizeNodeStatus(node.verificationStatus),
  };
}

/**
 * Save workspace state to localStorage.
 * Returns true on success, false on failure (e.g. QuotaExceededError).
 */
export type ArtifactPersistenceData = {
  causalGraph: string | null;
  statisticalModel: string | null;
  propertyTests: string | null;
  dialecticalMap: string | null;
  counterexamples: string | null;
  /** Generated output for custom artifact types, keyed by custom type ID */
  customArtifactData?: Record<string, string | null>;
};

export type SaveWorkspaceInput = {
  sourceText: string;
  extractedFiles: { name: string; text: string }[];
  contextText: string;
  semiformalText: string;
  leanCode: string;
  semiformalDirty: boolean;
  verificationStatus: VerificationStatus;
  verificationErrors: string;
  decomposition: PersistedDecomposition;
  artifacts?: ArtifactPersistenceData;
  customArtifactTypes?: CustomArtifactTypeDefinition[];
};

export function saveWorkspace(input: SaveWorkspaceInput): boolean {
  const artifacts = input.artifacts ?? { causalGraph: null, statisticalModel: null, propertyTests: null, dialecticalMap: null, counterexamples: null };
  const data: PersistedWorkspace = {
    version: WORKSPACE_VERSION,
    sourceText: input.sourceText,
    extractedFiles: input.extractedFiles,
    contextText: input.contextText,
    semiformalText: input.semiformalText,
    leanCode: input.leanCode,
    semiformalDirty: input.semiformalDirty,
    verificationStatus: sanitizeVerificationStatus(input.verificationStatus),
    verificationErrors: input.verificationErrors,
    decomposition: {
      ...input.decomposition,
      nodes: input.decomposition.nodes.map(sanitizeNode),
    },
    causalGraph: artifacts.causalGraph,
    statisticalModel: artifacts.statisticalModel,
    propertyTests: artifacts.propertyTests,
    dialecticalMap: artifacts.dialecticalMap,
    counterexamples: artifacts.counterexamples,
    customArtifactTypes: input.customArtifactTypes ?? [],
    customArtifactData: artifacts.customArtifactData ?? {},
  };

  try {
    localStorage.setItem(WORKSPACE_KEY, JSON.stringify(data));
    return true;
  } catch {
    return false;
  }
}

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** Validate that a deserialized object is a well-formed CustomArtifactTypeDefinition. */
export function isValidCustomTypeDef(v: unknown): v is CustomArtifactTypeDefinition {
  if (!isObject(v)) return false;
  return (
    typeof v.id === "string" && v.id.startsWith("custom-") &&
    typeof v.name === "string" && v.name.length > 0 &&
    typeof v.chipLabel === "string" && v.chipLabel.length > 0 &&
    typeof v.systemPrompt === "string" && v.systemPrompt.length > 0 &&
    (v.outputFormat === "json" || v.outputFormat === "text")
  );
}

export function coerceDecomposition(raw: unknown): PersistedDecomposition {
  if (!isObject(raw)) {
    return { nodes: [], selectedNodeId: null, paperText: "", sources: [] };
  }

  const nodes = Array.isArray(raw.nodes)
    ? (raw.nodes as unknown[]).filter(isObject).map((n) => ({
        id: typeof n.id === "string" ? n.id : "",
        label: typeof n.label === "string" ? n.label : "",
        kind: typeof n.kind === "string" ? n.kind : "proposition",
        statement: typeof n.statement === "string" ? n.statement : "",
        proofText: typeof n.proofText === "string" ? n.proofText : "",
        dependsOn: Array.isArray(n.dependsOn) ? (n.dependsOn as unknown[]).filter((d) => typeof d === "string") as string[] : [],
        sourceId: typeof n.sourceId === "string" ? n.sourceId : "",
        sourceLabel: typeof n.sourceLabel === "string" ? n.sourceLabel : "",
        semiformalProof: typeof n.semiformalProof === "string" ? n.semiformalProof : "",
        leanCode: typeof n.leanCode === "string" ? n.leanCode : "",
        verificationStatus: sanitizeNodeStatus(typeof n.verificationStatus === "string" ? n.verificationStatus : ""),
        verificationErrors: typeof n.verificationErrors === "string" ? n.verificationErrors : "",
        context: typeof n.context === "string" ? n.context : "",
        selectedArtifactTypes: Array.isArray(n.selectedArtifactTypes) ? n.selectedArtifactTypes as import("@/app/lib/types/session").ArtifactType[] : [],
        artifacts: Array.isArray(n.artifacts) ? n.artifacts as import("@/app/lib/types/decomposition").NodeArtifact[] : [],
      } as PropositionNode))
    : [];

  // Validate graphLayout: positions must be Record<string, {x: number, y: number}>
  let graphLayout: import("@/app/lib/types/decomposition").GraphLayout | undefined;
  if (isObject(raw.graphLayout)) {
    const rawLayout = raw.graphLayout as Record<string, unknown>;
    if (isObject(rawLayout.positions)) {
      const rawPositions = rawLayout.positions as Record<string, unknown>;
      const positions: Record<string, { x: number; y: number }> = {};
      for (const [key, val] of Object.entries(rawPositions)) {
        if (isObject(val) && typeof val.x === "number" && typeof val.y === "number") {
          positions[key] = { x: val.x, y: val.y };
        }
      }
      if (Object.keys(positions).length > 0) {
        graphLayout = { positions };
        if (isObject(rawLayout.viewport)) {
          const vp = rawLayout.viewport as Record<string, unknown>;
          if (typeof vp.x === "number" && typeof vp.y === "number" && typeof vp.zoom === "number") {
            graphLayout.viewport = { x: vp.x, y: vp.y, zoom: vp.zoom };
          }
        }
      }
    }
  }

  return {
    nodes,
    selectedNodeId: typeof raw.selectedNodeId === "string" ? raw.selectedNodeId : null,
    paperText: typeof raw.paperText === "string" ? raw.paperText : "",
    sources: Array.isArray(raw.sources) ? (raw.sources as unknown[]).filter(isObject).map((s) => ({
      sourceId: typeof s.sourceId === "string" ? s.sourceId : "",
      sourceLabel: typeof s.sourceLabel === "string" ? s.sourceLabel : "",
      text: typeof s.text === "string" ? s.text : "",
    })) : [],
    graphLayout,
  };
}

/**
 * Load workspace state from localStorage.
 * Returns null if no data, wrong version, or malformed.
 */
export function loadWorkspace(): PersistedWorkspace | null {
  try {
    migrateV1Workspace();
    const raw = localStorage.getItem(WORKSPACE_KEY);
    if (!raw) return null;

    const parsed: unknown = JSON.parse(raw);
    if (!isObject(parsed)) return null;
    if (parsed.version !== WORKSPACE_VERSION) return null;

    const decomposition = coerceDecomposition(parsed.decomposition);

    return {
      version: WORKSPACE_VERSION,
      sourceText: typeof parsed.sourceText === "string" ? parsed.sourceText : "",
      extractedFiles: Array.isArray(parsed.extractedFiles)
        ? (parsed.extractedFiles as unknown[])
            .filter(isObject)
            .map((f) => ({
              name: typeof f.name === "string" ? f.name : "",
              text: typeof f.text === "string" ? f.text : "",
            }))
        : [],
      contextText: typeof parsed.contextText === "string" ? parsed.contextText : "",
      semiformalText: typeof parsed.semiformalText === "string" ? parsed.semiformalText : "",
      leanCode: typeof parsed.leanCode === "string" ? parsed.leanCode : "",
      semiformalDirty: typeof parsed.semiformalDirty === "boolean" ? parsed.semiformalDirty : false,
      verificationStatus: sanitizeVerificationStatus(
        typeof parsed.verificationStatus === "string" ? parsed.verificationStatus : "",
      ),
      verificationErrors: typeof parsed.verificationErrors === "string" ? parsed.verificationErrors : "",
      decomposition,
      causalGraph: typeof parsed.causalGraph === "string" ? parsed.causalGraph : null,
      statisticalModel: typeof parsed.statisticalModel === "string" ? parsed.statisticalModel : null,
      propertyTests: typeof parsed.propertyTests === "string" ? parsed.propertyTests : null,
      dialecticalMap: typeof parsed.dialecticalMap === "string" ? parsed.dialecticalMap : null,
      counterexamples: typeof parsed.counterexamples === "string" ? parsed.counterexamples : null,
      customArtifactTypes: Array.isArray(parsed.customArtifactTypes)
        ? (parsed.customArtifactTypes as unknown[]).filter(isValidCustomTypeDef)
        : [],
      customArtifactData: isObject(parsed.customArtifactData)
        ? Object.fromEntries(
            Object.entries(parsed.customArtifactData as Record<string, unknown>)
              .filter(([, v]) => typeof v === "string" || v === null)
              .map(([k, v]) => [k, v as string | null]),
          )
        : {},
    };
  } catch {
    return null;
  }
}

