  if (!_sessionsCache) _sessionsCache = loadFromStorage();
  return _sessionsCache;
}

function getServerSnapshot(): WorkspaceSessionsState {
  return EMPTY_STATE;
}

function subscribeToSessions(cb: () => void): () => void {
  _listeners.add(cb);
  return () => _listeners.delete(cb);
