function phaseToEndpoint(phase: LoadingPhase): string | null {
  switch (phase) {
    case "semiformal":
      return "formalization/semiformal";
    case "lean":
    case "retrying":
    case "iterating":
      return "formalization/lean";
    case "verifying":
    case "reverifying":
      return "verification/lean";
    case "idle":
      return null;
  }
}

