86	/** Zero-padded version file, e.g. artifactVersionPath(s,"semiformal",1) ->
87	 *  "workspaces/<s>/artifacts/semiformal/v0001.md". `version` is 1-based. */
88	export function artifactVersionPath(slug: string, artifactType: string, version: number): string {
