96	export function artifactMetaPath(slug: string, artifactType: string): string {
97	  return `${artifactDir(slug, artifactType)}/meta.json`;
98	}
99	
100	export function customTypePath(slug: string, customTypeId: string): string {
101	  return `${workspaceDir(slug)}/custom-types/${safeSegment(customTypeId)}.json`;
102	}
103	
104	export function decompositionDir(slug: string): string {
105	  return `${workspaceDir(slug)}/decomposition`;
106	}
107	
108	export function decompositionGraphLayoutPath(slug: string): string {
109	  return `${decompositionDir(slug)}/graph-layout.json`;
110	}
