     1	/** Returns a throttled version of `fn` that runs at most once per `ms` milliseconds.
     2	 *  The last call is always delivered (trailing edge).
     3	 *  Call `.cancel()` to clear any pending trailing-edge timer. */
     4	export function throttle<T extends (...args: Parameters<T>) => void>(
     5	  fn: T,
     6	  ms: number,
     7	): ((...args: Parameters<T>) => void) & { cancel: () => void } {
     8	  let lastRun = 0;
     9	  let timer: ReturnType<typeof setTimeout> | null = null;
    10	
    11	  const throttled = (...args: Parameters<T>) => {
    12	    const now = Date.now();
    13	    const remaining = ms - (now - lastRun);
    14	
    15	    if (remaining <= 0) {
    16	      if (timer) { clearTimeout(timer); timer = null; }
    17	      lastRun = now;
    18	      fn(...args);
    19	    } else if (!timer) {
    20	      timer = setTimeout(() => {
    21	        lastRun = Date.now();
    22	        timer = null;
    23	        fn(...args);
    24	      }, remaining);
    25	    }
    26	  };
    27	
    28	  throttled.cancel = () => {
    29	    if (timer) { clearTimeout(timer); timer = null; }
    30	  };
    31	
    32	  return throttled;
    33	}
