1	/**
2	 * Storage-seam selection for the Zustand workspace store (DD-009 sub-task S1).
3	 *
4	 * `resolveWorkspaceStorage()` returns the zustand persist storage: the existing
5	 * debounced localStorage adapter by default, or a CorpusFS-backed storage when
6	 * the dev flag is on. The injection seam is typed as `CorpusFS` (arch-review
7	 * finding 3) so the S3 worker-proxy implementation drops in here without the
8	 * store ever knowing which adapter it talks to.
9	 *
10	 * In S1 the persist blob is stored as a SINGLE file via CorpusFS (blob mode) —
11	 * the files-per-artifact folder layout (layout.ts/manifest.ts) is built but not
12	 * used by the store until S4. This keeps S1 a pure substrate swap.
13	 */
14	
15	import type { StateStorage } from "zustand/middleware";
16	import type { CorpusFS } from "./types";
17	import { createOpfsCorpusFs } from "./opfsAdapter";
18	import { isCorpusEnabled } from "./flag";
19	
20	// ---------------------------------------------------------------------------
21	// Default: debounced localStorage (moved verbatim from workspaceStore.ts so the
22	// OFF path is byte-for-byte the prior behavior — see the characterization test).
23	// Reads are synchronous (instant); writes are debounced by 300ms.
24	// ---------------------------------------------------------------------------
25	export function createDebouncedLocalStorage(): StateStorage {
26	  let pending: ReturnType<typeof setTimeout> | null = null;
27	  return {
28	    getItem: (name) => localStorage.getItem(name),
29	    setItem: (name, value) => {
30	      if (pending) clearTimeout(pending);
31	      pending = setTimeout(() => {
32	        try {
33	          localStorage.setItem(name, value);
34	        } catch (e) {
35	          console.warn("Failed to persist workspace (localStorage quota exceeded):", e);
36	        }
37	        pending = null;
38	      }, 300);
39	    },
40	    removeItem: (name) => {
41	      if (pending) clearTimeout(pending);
42	      pending = null;
43	      localStorage.removeItem(name);
44	    },
45	  };
46	}
47	
48	// ---------------------------------------------------------------------------
49	// Corpus-backed storage: stores the persist blob as one file under `state/`.
50	// The seam type is CorpusFS, not a concrete adapter (arch-review finding 3).
51	// ---------------------------------------------------------------------------
52	export function createCorpusBackedStorage(fs: CorpusFS): StateStorage {
53	  const enc = new TextEncoder();
54	  const dec = new TextDecoder();
55	  const pathFor = (name: string) => `state/${name}.json`;
56	  return {
57	    getItem: async (name) => {
58	      const bytes = await fs.readFile(pathFor(name));
59	      return bytes ? dec.decode(bytes) : null;
60	    },
61	    setItem: async (name, value) => {
62	      await fs.writeFile(pathFor(name), enc.encode(value));
63	    },
64	    removeItem: async (name) => {
65	      await fs.rm(pathFor(name));
66	    },
67	  };
68	}
69	
70	/** Selected once when the store's persist middleware initializes. */
71	export function resolveWorkspaceStorage(): StateStorage {
72	  if (isCorpusEnabled()) {
73	    return createCorpusBackedStorage(createOpfsCorpusFs());
74	  }
75	  return createDebouncedLocalStorage();
76	}
